"""Adds the extra Amirnet question types (original practice items written to the official formats):
wf = word formation, gc = grammar in context, lc = listening text continuation, lq = lecture / conversation, wr = writing task.
Run: python3 tools/add_types.py  (idempotent: replaces earlier n* ids/sets)"""
import json
P='src/amiram.json'
D=json.load(open(P))
D['q']={k:v for k,v in D['q'].items() if not k.startswith('n')}
D['x']={k:v for k,v in D['x'].items() if not k.startswith('n')}
D['s']=[s for s in D['s'] if not s['id'].startswith('n')]

